From 7d111807fb6249fb5ef224aa08a8a0eb72a9b7e9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:27:14 +0100
Subject: [PATCH] applets/taskmanager: allow dragging windows out of the
 tooltip

Window thumbnails in a grouped task's tooltip had no drag source, so one
window of the group couldn't be dropped on an activity in the sidebar.
Add a drag handler that carries that window's drag data, like a task.

BUG: 442499
---
 applets/taskmanager/qml/ToolTipInstance.qml | 34 +++++++++++++++++++++
 1 file changed, 34 insertions(+)

diff --git a/applets/taskmanager/qml/ToolTipInstance.qml b/applets/taskmanager/qml/ToolTipInstance.qml
index 5a42d24a17..7679021ddf 100644
--- a/applets/taskmanager/qml/ToolTipInstance.qml
+++ b/applets/taskmanager/qml/ToolTipInstance.qml
@@ -20,6 +20,7 @@ import org.kde.plasma.components as PlasmaComponents3
 import org.kde.plasma.extras as PlasmaExtras
 import org.kde.kirigami as Kirigami
 import org.kde.kwindowsystem
+import org.kde.taskmanager as TaskManager

 ColumnLayout {
     id: root
@@ -260,6 +261,31 @@ ColumnLayout {
             }
         }

+        component ToolTipDragHandler: DragHandler {
+            id: dragHandler
+            target: null
+
+            onActiveChanged: {
+                if (active) {
+                    parent.grabToImage(result => {
+                        if (!dragHandler.active) {
+                            return;
+                        }
+                        const mimeData = tasksModel.data(root.submodelIndex, TaskManager.AbstractTasksModel.MimeData);
+                        dragHelper.Drag.imageSource = result.url;
+                        dragHelper.Drag.mimeData = {
+                            [tasksModel.data(root.submodelIndex, TaskManager.AbstractTasksModel.MimeType)]: mimeData,
+                            "application/x-orgkdeplasmataskmanager_taskbuttonitem": mimeData,
+                        };
+                        dragHelper.Drag.active = dragHandler.active;
+                    }, Qt.size(parent.width / 2, parent.height / 2));
+                } else {
+                    dragHelper.Drag.active = false;
+                    dragHelper.Drag.imageSource = "";
+                }
+            }
+        }
+
         ToolTipHoverHandler {
             id: headerHoverHandler
             enabled: (root.index !== -1) && !Plasmoid.configuration.showToolTips && thumbnailSourceItem.winId != undefined
@@ -270,6 +296,10 @@ ColumnLayout {
             enabled: (root.index !== -1) && !Plasmoid.configuration.showToolTips && thumbnailSourceItem.winId != undefined
         }

+        ToolTipDragHandler {
+            enabled: headerTapHandler.enabled
+        }
+
         // There's no PlasmaComponents3 version
         PlasmaExtras.Highlight {
             id: headerHoverHighlight
@@ -395,6 +425,10 @@ ColumnLayout {
             id: tapHandler
             enabled: root.index !== -1 && Plasmoid.configuration.showToolTips && thumbnailSourceItem.winId != undefined
         }
+
+        ToolTipDragHandler {
+            enabled: tapHandler.enabled
+        }
     }

     // Player controls row, load on demand so group tooltips could be loaded faster
-- 
2.53.0
